// Construye el correo HTML con las propiedades que coinciden con la alerta
const a = $json;
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (n, m) => n ? '$' + Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 }) + ' ' + (m || 'USD') : 'Consultar';
const lista = Array.isArray(a.inmuebles) ? a.inmuebles : [];

const tarjetas = lista.map(i => `
  <tr><td style="padding:0 0 16px 0">
    <a href="${esc(i.url)}" style="text-decoration:none;color:inherit;display:block;border:1px solid #E5E7EB;border-radius:16px;overflow:hidden">
      ${i.foto ? `<img src="${esc(i.foto)}" alt="" width="536" style="display:block;width:100%;height:220px;object-fit:cover">` : ''}
      <div style="padding:16px 18px">
        <div style="font-size:22px;font-weight:800;color:#0B4A3F">${esc(fmt(i.precio, i.moneda))}</div>
        <div style="font-size:15px;font-weight:700;color:#111827;margin-top:4px">${esc(i.titulo)}</div>
        <div style="font-size:13px;color:#6B7280;margin-top:6px">📍 ${esc(i.zona)}${i.habitaciones ? ' · 🛏 ' + esc(i.habitaciones) : ''}${i.banos ? ' · 🛁 ' + esc(i.banos) : ''}${i.m2 ? ' · 📐 ' + esc(i.m2) : ''}</div>
        <div style="margin-top:12px;font-size:13px;font-weight:700;color:#10B981">Ver inmueble →</div>
      </div>
    </a>
  </td></tr>`).join('');

const nombre = (a.nombre || '').split(' ')[0];
const titulo = a.total === 1 ? 'Encontramos un inmueble para ti' : `Encontramos ${a.total} inmuebles para ti`;

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;background:#F3F4F6;font-family:Montserrat,Arial,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F3F4F6;padding:24px 12px"><tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#FFFFFF;border-radius:20px;overflow:hidden">
  <tr><td style="background:#0B4A3F;padding:22px 32px;color:#FFFFFF;font-size:18px;font-weight:800">MAXIMUS<span style="color:#10B981">.</span> <span style="font-size:11px;font-weight:600;letter-spacing:2px;color:#A7F3D0">INMOBILIARIA</span></td></tr>
  <tr><td style="padding:28px 32px 8px 32px">
    <div style="font-size:12px;font-weight:700;letter-spacing:1.5px;color:#10B981;text-transform:uppercase">🔔 Tu alerta de búsqueda</div>
    <h1 style="margin:8px 0 6px 0;font-size:24px;color:#111827">${nombre ? esc(nombre) + ', ' : ''}${titulo.charAt(0).toLowerCase() + titulo.slice(1)}</h1>
    <p style="margin:0 0 20px 0;font-size:14px;color:#6B7280">Coinciden con lo que buscas: <strong style="color:#111827">${esc(a.resumen)}</strong></p>
  </td></tr>
  <tr><td style="padding:0 32px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${tarjetas}</table></td></tr>
  <tr><td style="padding:8px 32px 28px 32px" align="center">
    <a href="https://wa.me/584247835697?text=${encodeURIComponent('Hola MAXIMUS, me llegó una alerta de búsqueda y quiero más información.')}" style="display:inline-block;background:#0B4A3F;color:#FFFFFF;text-decoration:none;font-weight:700;font-size:14px;padding:13px 26px;border-radius:12px">Hablar con un asesor</a>
  </td></tr>
  <tr><td style="padding:18px 32px;background:#F9FAFB;font-size:11px;color:#9CA3AF;text-align:center">Recibes este correo porque creaste una alerta en MAXIMUS. Puedes pausarla o borrarla desde <a href="https://maximusinmobiliaria.tech/dashboard#view-inmuebles" style="color:#0B4A3F">Mis alertas</a> en tu panel.</td></tr>
</table></td></tr></table></body></html>`;

return {
  json: {
    ...a,
    asunto: `🏠 ${titulo}: ${a.resumen}`,
    html
  }
};
